    "topic_math_stats": "Math & stats",
    "topic_math_stats_title": "Math & statistics tools",
    "topic_math_stats_desc": "Mean, median, SD, z-score, p-value, CIs, sample size, permutations, GPA, exponents, logs, sci notation, sig figs, and quadratics for school and analytics work.",
